{
    "data": {
        "type": "authorization",
        "attributes": {
            "validity_type": "<(none|validity_date|bis_case_stages)>",
            "validity_date": "<Date (optional)>",
            "bis_case_stages": ["<(Iecere|Būvniecības ieceres publiskā apspriešana|Projektēšanas nosacījumu izpilde|Būvdarbu uzsākšanas nosacījumu izpilde|Būvdarbi|Nodošana ekspluatācijā|Ekspluatācija)> (optional)"],
            "apply_all_bis_cases": "<Boolean>",
            "bis_case_ids": [{{bis_case_id1}}, {{bis_case_id2}}]
        },
        "relationships": {
            "authorization_member": {
                "data": {
                    "attributes": {
                        "member_type": "receiver",
                        "person_type": "<(certificate|construction_merchant)>",
                        "certificate_id": {{certificate_id}},
                        "construction_merchant_id": {{construction_merchant_id}}
                    }
                }
            },
            "authorization_rights": {
                "data": [
                    {
                        "attributes": {
                            "configuration_right_id": {{configuration_right_id1}},
                            "reassign": "<Boolean>"
                        }
                    },
                    {
                        "attributes": {
                            "configuration_right_id": {{configuration_right_id2}},
                            "reassign": "<Boolean>"
                        }
                    }
                ]
            },
            "attachments": {
                "data": [
                    { "uuid": "{{temp_uuid}}" }
                ]
            }
        }
    }
}

